<?php
require __DIR__.'/app/lib.php';
require __DIR__.'/app/landHelpers.php';
$me=user();if(!$me)go('index.php?page=login');
$error='';$owner=$_SESSION['role']==='farmer';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{require __DIR__.'/app/landActions.php';}
 catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();if($ex instanceof PDOException){error_log($ex->getMessage());$error='Could not save this record. Please check your values and try again.';}else $error=$ex->getMessage();}
}
$land=null;$cycle=null;$cycles=[];$cost=null;$entries=[];$editExpense=null;
try{
 if(isset($_GET['land'])){
  $land=land_record((int)$_GET['land'],$me);
  $cycles=query('SELECT c.*,v.total_cost,v.entry_count FROM crop_cycles c JOIN v_land_costs v ON v.cycle_id=c.id WHERE c.land_id=? ORDER BY c.sowing_date DESC,c.id DESC',[$land['id']])->fetchAll();
  foreach($cycles as $row)if((isset($_GET['cycle']) && (int)$_GET['cycle']===(int)$row['id']) || (!isset($_GET['cycle']) && !$cycle))$cycle=$row;
  if(isset($_GET['cycle']) && !$cycle)throw new RuntimeException('Crop season not found for this land.');
  if($cycle){$cost=query('SELECT * FROM v_land_costs WHERE cycle_id=?',[$cycle['id']])->fetch();$entries=query('SELECT * FROM land_expenses WHERE cycle_id=? ORDER BY expense_date DESC,id DESC',[$cycle['id']])->fetchAll();foreach($entries as $row)if((int)($_GET['edit_expense']??0)===(int)$row['id'])$editExpense=$row;}
 }
}catch(RuntimeException $ex){$error=$ex->getMessage();$land=null;$cycle=null;}
[$scope,$params]=land_scope($me);
$lands=query('SELECT l.*,f.name AS farmer_name,t.name AS thana_name,d.name AS district_name,(SELECT COUNT(*) FROM crop_cycles c WHERE c.land_id=l.id) AS seasons,(SELECT COALESCE(SUM(v.total_cost),0) FROM v_land_costs v WHERE v.land_id=l.id) AS spent FROM lands l JOIN farmers f ON f.id=l.farmer_id JOIN thanas t ON t.code=l.thana_code JOIN districts d ON d.code=t.district_code WHERE '.$scope.' ORDER BY l.archived,l.name,l.id',$params)->fetchAll();
$totalArea=array_sum(array_column($lands,'area_sqft'));$totalSpent=array_sum(array_column($lands,'spent'));
page_start('Land management',$me);?>
<main class="dashboard land-workspace">
 <div class="dashboard-heading"><div><span class="eyebrow">KRISHI / KNOW YOUR FARM</span><h1><?=$owner?'Your land. Your progress.':'Land & financial review'?></h1><p class="muted"><?=$owner?'Keep each plot, growing season and taka accounted for.':($_SESSION['role']==='admin'?'Review all registered lands and cultivation costs.':'Review farmer-declared land and cultivation costs in your district.')?></p></div><a class="button" href="<?= $owner ? 'index.php?page=schemes' : 'index.php#schemes' ?>">Scheme applications ↗</a></div>
 <?php if($error):?><p class="error" role="alert"><?=e($error)?></p><?php endif;?>
 <section class="stats land-stats"><div><span>Registered plots</span><strong><?=count($lands)?></strong><small>Active and archived records</small></div><div><span>Total registered area</span><strong><?=number_format($totalArea/720,2)?></strong><small>Katha · 720 sq ft per katha</small></div><div><span>Recorded expenses</span><strong><?=number_format($totalSpent,2)?></strong><small>BDT · all crop seasons</small></div></section>
 <div class="land-layout"><aside class="land-directory panel"><div class="section-heading"><h2><?=$owner?'My lands':($_SESSION['role']==='admin'?'All lands':'District lands')?></h2><?php if($owner):?><a href="land.php?new=1#land-form">+ Add land</a><?php endif;?></div>
 <label>Find a land<input id="land-search" type="search" placeholder="Land, farmer or location"></label>
 <?php if(!$lands):?><p class="muted">No registered land yet. <?=$owner?'Add your first plot below.':'Only active farmers’ lands in your district are shown.'?></p><?php endif;?>
 <?php foreach($lands as $l):?><a class="land-link <?=($land && $land['id']==$l['id'])?'selected':''?>" data-land-search="<?=e(strtolower($l['name'].' '.$l['farmer_name'].' '.$l['district_name']))?>" href="land.php?land=<?=$l['id']?>"><strong><?=e($l['name'])?> <?=$l['archived']?'(archived)':''?></strong><span><?=e($l['farmer_name'])?> · <?=e($l['district_name'])?></span><span><?=number_format((float)$l['area_sqft']/LAND_UNITS[$l['display_unit']],3)?> <?=e($l['display_unit'])?> · <?=e(land_money($l['spent']))?></span></a><?php endforeach;?><p id="land-no-match" hidden>No matching lands.</p>
 <small class="muted">Area conversion uses a fixed 720 sq ft katha. If your local katha differs, enter square feet or acres.</small></aside>
 <section class="land-main">
 <?php if($owner && (!$land || isset($_GET['edit_land']) || isset($_GET['new']))):
 $edit=isset($_GET['edit_land'])?$land:null;$places=query('SELECT t.code,t.name,d.name AS district_name FROM thanas t JOIN districts d ON d.code=t.district_code ORDER BY d.name,t.name')->fetchAll();?>
 <section class="panel" id="land-form"><span class="eyebrow">YOUR LAND REGISTER</span><h2><?=$edit?'Edit land details':'Add a land'?></h2><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="save_land"><input type="hidden" name="land_id" value="<?=e($edit['id']??0)?>">
 <label>Land name<input name="name" maxlength="100" required placeholder="North field" value="<?=e($edit['name']??'')?>"></label><label>Thana / Upazila<select name="thana_code" required><option value="">Select the land’s location</option><?php foreach($places as $place):?><option value="<?=e($place['code'])?>" <?=($edit['thana_code']??'')===$place['code']?'selected':''?>><?=e($place['district_name'].' · '.$place['name'])?></option><?php endforeach;?></select></label>
 <label>Land address / plot reference<input name="address" maxlength="255" required placeholder="Village, road, mouza and plot number if known" value="<?=e($edit['address']??'')?>"></label>
 <div class="two"><label>Area<input type="number" name="area" min="0.0001" max="100000000" step="0.0001" required value="<?=$edit?e(number_format((float)$edit['area_sqft']/LAND_UNITS[$edit['display_unit']],4,'.','')):''?>"></label><label>Unit<select name="display_unit"><?php foreach(LAND_UNITS as $unit=>$factor):?><option value="<?=$unit?>" <?=($edit['display_unit']??'katha')===$unit?'selected':''?>><?=e($unit==='katha'?'Katha (720 sq ft)':ucfirst($unit))?></option><?php endforeach;?></select></label></div>
 <div class="two"><label>Tenure<select name="tenure"><?php foreach(['owned','leased','shared'] as $v):?><option <?=($edit['tenure']??'owned')===$v?'selected':''?> value="<?=$v?>"><?=ucfirst($v)?></option><?php endforeach;?></select></label><label>Soil type<input name="soil_type" maxlength="100" placeholder="e.g. Loamy" value="<?=e($edit['soil_type']??'')?>"></label></div>
 <label>Irrigation source<input name="irrigation" maxlength="100" placeholder="e.g. Rainfed, pump, canal" value="<?=e($edit['irrigation']??'')?>"></label><label>Notes<textarea name="notes" maxlength="1000" rows="2"><?=e($edit['notes']??'')?></textarea></label><button>Save land →</button></form></section>
 <?php endif;?>
 <?php if($land):?>
 <section class="panel land-heading"><div class="section-heading"><div><span class="eyebrow"><?=e($land['farmer_name'])?> / <?=e($land['tenure'])?></span><h2><?=e($land['name'])?></h2></div><?php if($owner):?><a href="land.php?land=<?=$land['id']?>&edit_land=1#land-form">Edit land</a><?php endif;?></div>
 <p><?=e($land['address'].' · '.$land['thana_name'].' · '.$land['district_name'])?></p><p><strong><?=number_format((float)$land['area_sqft']/LAND_UNITS[$land['display_unit']],3)?> <?=e($land['display_unit'])?></strong> · <?=number_format((float)$land['area_sqft'],2)?> sq ft · <?=e($land['soil_type']?:'Soil not recorded')?> · <?=e($land['irrigation']?:'Irrigation not recorded')?></p>
 <?php if($land['notes']):?><p class="muted"><?=nl2br(e($land['notes']))?></p><?php endif;?>
 <?php if($owner):?><form method="post" data-confirm="<?=$land['archived']?'Restore this land?':'Archive this land? History stays available and its area still counts in scheme land totals.'?>"><?=csrf()?><input type="hidden" name="action" value="archive_land"><input type="hidden" name="land_id" value="<?=$land['id']?>"><button class="text-button"><?=$land['archived']?'Restore land':'Archive land'?></button></form><?php endif;?></section>
 <section class="panel"><div class="section-heading"><h2>Crop seasons</h2><?php if($owner && !$land['archived']):?><a href="land.php?land=<?=$land['id']?>&new_cycle=1#cycle-form">+ New season</a><?php endif;?></div>
 <div class="season-tabs"><?php foreach($cycles as $c):?><a class="<?=($cycle && $cycle['id']==$c['id'])?'selected':''?>" href="land.php?land=<?=$land['id']?>&cycle=<?=$c['id']?>"><?=e($c['crop'].' · '.$c['season'])?> <small><?=e($c['status'])?></small></a><?php endforeach;?></div><?php if(!$cycles):?><p class="muted">Add a crop season before recording expenses or applying for a scheme.</p><?php endif;?></section>
 <?php if($owner && !$land['archived'] && (!$cycles || isset($_GET['new_cycle']) || isset($_GET['edit_cycle']))):$c=isset($_GET['edit_cycle'])?$cycle:null;?>
 <section class="panel" id="cycle-form"><h2><?=$c?'Edit crop season':'Add a crop season'?></h2><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="save_cycle"><input type="hidden" name="land_id" value="<?=$land['id']?>"><input type="hidden" name="cycle_id" value="<?=e($c['id']??0)?>"><div class="two"><label>Crop<input name="crop" maxlength="100" required value="<?=e($c['crop']??'')?>" placeholder="Rice"></label><label>Variety (optional)<input name="variety" maxlength="100" value="<?=e($c['variety']??'')?>"></label></div><label>Season name<input name="season" maxlength="100" required placeholder="Aman 2026" value="<?=e($c['season']??'')?>"></label><div class="two"><label>Sowing / start date<input type="date" name="sowing_date" required value="<?=e($c['sowing_date']??date('Y-m-d'))?>"></label><label>Expected harvest<input type="date" name="expected_harvest" value="<?=e($c['expected_harvest']??'')?>"></label></div><div class="two"><label>Budget (BDT)<input type="number" name="budget" min="0" max="9999999999.99" step="0.01" required value="<?=e($c['budget']??0)?>"></label><label>Status<select name="status"><?php foreach(['planned','growing','harvested'] as $status):?><option value="<?=$status?>" <?=($c['status']??'growing')===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></label></div><button>Save crop season</button></form></section><?php endif;?>
 <?php if($cycle):$remaining=(float)$cycle['budget']-(float)$cost['total_cost'];?>
 <section class="panel"><div class="section-heading"><div><span class="eyebrow"><?=e($cycle['season'].' / '.$cycle['status'])?></span><h2><?=e($cycle['crop'])?> costs</h2></div><?php if($owner && !$land['archived']):?><a href="land.php?land=<?=$land['id']?>&cycle=<?=$cycle['id']?>&edit_cycle=1#cycle-form">Edit season</a><?php endif;?></div><p class="muted">Sown <?=e($cycle['sowing_date'])?><?= $cycle['expected_harvest']?' · Expected harvest '.e($cycle['expected_harvest']):''?></p>
 <div class="cost-summary"><div><small>Recorded spending</small><strong><?=e(land_money($cost['total_cost']))?></strong></div><div><small>Budget</small><strong><?=e(land_money($cycle['budget']))?></strong></div><div class="<?=$remaining<0?'over-budget':''?>"><small><?=$remaining<0?'Over budget':'Budget remaining'?></small><strong><?=e(land_money(abs($remaining)))?></strong></div></div>
 <?php $byCategory=query('SELECT category,SUM(amount) AS total FROM land_expenses WHERE cycle_id=? GROUP BY category ORDER BY total DESC',[$cycle['id']])->fetchAll();foreach($byCategory as $cat):?><div class="cost-bar"><span><?=e(COST_CATEGORIES[$cat['category']])?></span><meter min="0" max="<?=max(1,(float)$cost['total_cost'])?>" value="<?=e($cat['total'])?>"></meter><strong><?=e(land_money($cat['total']))?></strong></div><?php endforeach;?>
 <p class="muted">Cost per <?=e($land['display_unit'])?>: <?=e(land_money((float)$cost['total_cost']/((float)$land['area_sqft']/LAND_UNITS[$land['display_unit']])))?>. All totals belong to this crop season.</p></section>
 <?php if($owner && !$land['archived']):require __DIR__.'/app/expenseForm.php';endif;?>
 <section class="panel"><h2>Expense history</h2><?php if(!$entries):?><p class="muted">No costs recorded in this season yet.</p><?php else:?><div class="table-scroll"><table class="expense-table"><thead><tr><th>Date / category</th><th>Item</th><th>Calculation</th><th>Total</th><?php if($owner):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($entries as $entry):?><tr><td><?=e($entry['expense_date'])?><small><?=e(COST_CATEGORIES[$entry['category']])?></small></td><td><?=e($entry['item'])?><small><?=e($entry['note']??'')?></small></td><td><?=e($entry['quantity'].' '.$entry['unit'])?><small>× <?=e(land_money($entry['unit_cost']))?></small></td><td><?=e(land_money($entry['amount']))?></td><?php if($owner):?><td><?php if(!$land['archived']):?><a href="land.php?land=<?=$land['id']?>&cycle=<?=$cycle['id']?>&edit_expense=<?=$entry['id']?>#expense-form">Edit</a><form method="post" data-confirm="Delete this expense? Submitted scheme snapshots stay unchanged."><?=csrf()?><input type="hidden" name="action" value="delete_expense"><input type="hidden" name="land_id" value="<?=$land['id']?>"><input type="hidden" name="cycle_id" value="<?=$cycle['id']?>"><input type="hidden" name="expense_id" value="<?=$entry['id']?>"><button class="text-button">Delete</button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
 <?php endif;elseif(!$owner):?><section class="empty"><h2>Select a land to review</h2><p>See the farmer’s crop seasons, itemized costs and budget. Scheme decisions use a separate saved submission snapshot.</p></section><?php endif;?>
 </section></div></main><?php page_end();?>
